"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[13966],{34011:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"MobileStatusGuiController","desc":"Phone-only status strip (`StarterGui.MobileStatusGui`): HP (+ shield),\\nstamina and train fuel side by side, centred just above the Satchel\\nhotbar. Runs only when `MobileHud.IsActive()`; the PC HUDs stay off then.\\n\\nEach `RenderStepped` it feeds `MobileStatusLogic.step` (hits, critical HP,\\nfuel shortage, low stamina while sprinting, alive) and swaps the strip and\\nthe expand pill when the view changes. Timings and thresholds live in\\n`MobileStatusConfig`.\\n\\n```\\nMobileStatusGui (IgnoreGuiInset, same space as Satchel\'s BackpackGui)\\n\u251c\u2500\u2500 Strip (UICorner, UIStroke, UIScale, UIPadding, UIListLayout)\\n\u2502   \u251c\u2500\u2500 Health  { Icon, Bars { Cells, ShieldCells }, Value }\\n\u2502   \u251c\u2500\u2500 Stamina { Icon, Cells, Value }\\n\u2502   \u251c\u2500\u2500 Fuel    { Icon, Cells, Value }\\n\u2502   \u2514\u2500\u2500 CollapseSlot { Chevron, Hit }\\n\u2514\u2500\u2500 ExpandPill (UICorner, UIStroke, UIScale) { Content { Heart, Chevron }, Hit }\\n```\\n\\nEvery Cells row is Cell1..10 { Fill }; cell i shows\\n`clamp(frac * 10 - (i - 1), 0, 1)`. Names are load-bearing; keep them in\\nsync with Studio. See docs/systems/mobile-status-hud.md.","realm":["Client"],"source":{"line":30,"path":"src/StarterPlayer/StarterPlayerScripts/MobileStatusGuiController.client.luau"}}')}}]);